<script setup>
import InvoiceTypeTags from "./InvoiceTypeTags.vue";
import AppIcon from "./AppIcon.vue";
import { invoiceExpenseColumns } from "../lib/expense-columns";
import { ref } from 'vue';
import { invoiceStore, invoiceActions } from '../invoiceStore.js';
import { importExpenseWorkbook } from '../lib/expense-import';
defineProps({ standalone: Boolean });
const files=ref([]), rows=ref([]), period=ref(''), message=ref(''), busy=ref(false);const preview=ref(null);let base=null;
function inferPeriod(path){return path.match(/20\d{2}\.\d{1,2}\.\d{1,2}-20\d{2}\.\d{1,2}\.\d{1,2}/)?.[0] || path.match(/20\d{2}年[一二三四1234]季度/)?.[0] || '';}
async function prepare(e){files.value=Array.from(e.target.files||[]).filter(f=>/\.xlsx?$/i.test(f.name)&&!f.name.startsWith('~$'));e.target.value='';const path=files.value[0]?.webkitRelativePath||files.value[0]?.name||'';period.value='';await build();}
async function build(){busy.value=true;message.value='';try{base=invoiceStore.ledger;let ledger=base;let review=[];for(const file of files.value){const r=importExpenseWorkbook(ledger,await file.arrayBuffer(),{period:period.value.trim() || inferPeriod(file.webkitRelativePath||file.name),sourceName:file.webkitRelativePath||file.name});ledger=r.ledger;review.push(...r.review);}const blocked=new Set(review.filter(r=>r.status==="冲突"||r.status==="待核对").map(r=>r.number));for(const number of blocked){if(base[number])ledger[number]=base[number];else delete ledger[number];}for(const row of review)if(row.status==="匹配"&&blocked.has(row.number)){row.status="冲突";row.reason="其他来源的同号记录存在冲突";}rows.value=review;preview.value={ledger};if(!review.length)message.value='未识别到发票报销记录；付款清单请到“付款凭证”导入。';}catch(e){message.value=e.message;}finally{busy.value=false;}}
function apply(){if(base!==invoiceStore.ledger){message.value='台账已变化，请重新核对';return;}try{invoiceActions.applyExpensePreview(preview.value);message.value='已更新匹配记录，未新增发票。';preview.value=null;rows.value=[];}catch(e){message.value=e.message;}}
</script><template><component :is="standalone ? 'section' : 'details'" class="expense-import" :class="{standalone}"><summary v-if="!standalone"><AppIcon name="upload" :size="17" />导入报销记录<span v-if="rows.length" class="soft-badge">{{ rows.length }} 条待确认</span></summary><div class="expense-import-body"><div class="finance-toolbar"><label class="btn-primary file-button"><AppIcon name="upload" :size="16" />选择报销 Excel<input type="file" accept=".xlsx,.xls" multiple :disabled="busy" @change="prepare" /></label><label class="btn file-button"><AppIcon name="folder" :size="16" />选择文件夹<input type="file" webkitdirectory multiple :disabled="busy" @change="prepare" /></label><label class="toolbar-field">报销期间<input v-model="period" placeholder="自动识别，也可手动填写" @input="preview=null" /></label><button class="btn" :disabled="busy||!files.length" @click="build">{{ busy?'核对中…':'重新核对' }}</button></div><p v-if="message" role="status" class="finance-notice">{{ message }}</p><template v-if="rows.length"><div class="finance-filterbar"><span class="status-pill success">匹配 {{ rows.filter(r=>r.status==='匹配').length }}</span><span class="status-pill warning">待处理 {{ rows.filter(r=>r.status!=='匹配').length }}</span><span class="table-count">不会新增发票</span></div><div class="finance-table-wrap import-result-table"><table class="finance-table"><thead><tr><th>核对结果</th><th v-for="[key,label] in invoiceExpenseColumns" :key="key">{{ label }}</th><th>报销期间</th><th>来源</th><th>待处理原因</th></tr></thead><tbody><tr v-for="(r,i) in rows" :key="i"><td><span class="status-pill" :class="r.status==='匹配'?'success':'warning'">{{ r.status }}</span></td><td v-for="[key] in invoiceExpenseColumns" :key="key" :class="{'number-cell':key==='total'}"><InvoiceTypeTags v-if="key==='type'" :entry="r" /><template v-else>{{ r[key]??'—' }}</template></td><td>{{ r.period||'未知' }}</td><td>{{ r.source }}</td><td>{{ r.status==='匹配'?'—':r.reason }}</td></tr></tbody></table></div><div class="finance-dialog-footer"><span class="field-hint">仅更新匹配记录；有期间的标记已报销</span><button class="btn-primary" :disabled="busy||!preview" @click="apply"><AppIcon name="check" :size="16" />确认导入</button></div></template></div></component></template>

<style scoped>
.expense-import.standalone{border:0;margin:0}.standalone .expense-import-body{padding:8px 0 0}
</style>
